    "Correta (C). Conforme a resolução: A partir da anarquia militar que sacudiu o Império entre 235 e 284, o poderio de Roma entrou em irremediável decadência, inclusive no plano militar. Entre outros aspectos da crise que debilitou o chamado “Baixo Império Romano”, destacou-se a carência de escravos, que reduziu a atividade produtiva e a arrecadação tributária – fatores que se refletiram na progressiva perda de poder dos imperadores. Paralelamente, verificou-se uma penetração cada vez maior de bárbaros germânicos, culminando com as grandes invasões de 406 e, no limite, com a queda do Império Romano do Ocidente, em 476.",
