  "n": 31,
  "subject": "Geografia",
  "content": "Clima e atmosfera",
  "detail": "Clima e atmosfera",
  "difficulty": "Média",
  "statement": "(https://earthdata.nasa.gov)\n\nO furacão é um sistema circular que se estende a alturas de 12 km a 14 km formando uma coluna elevada de ar em espiral. Um furacão como o da imagem ocorre",
  "blockTypes": [
    "source",
    "command"
  ],
  "alternatives": [
    "no hemisfério sul em uma superfície oceânica aquecida a cerca de 27 ºC.",
    "no hemisfério sul em uma superfície oceânica fria a cerca de 17 ºC.",
    "na linha do equador em uma superfície oceânica aque cida a cerca de 27 ºC.",
    "no hemisfério norte em uma superfície oceânica fria a cerca de 17 ºC.",
    "no hemisfério norte em uma superfície oceânica aque cida a cerca de 27 ºC."
  ],
  "answer": "E",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Um furacão se forma porque a água de um mar conserva calor, aquecendo também o ar sobre ele, com temperatura acima de 26°C, a evaporação é acelerada e o vapor é absorvido pelo ar que fica mais quente e úmido. O ar quente sobe formando uma coluna de baixa pressão em volta da qual sopram os ventos. No hemisfério sul, os furacões giram no sentido horário; e no hemisfério norte, no sentido oposto."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
