  "statement": "Acampamentos de imigrantes vindos da Venezuela foram destruídos por brasileiros em 18.08.2018, em Pacaraima (RR), na fronteira com o país vizinho, que sofre com uma crise humanitária e econômica.\n\n(www.correiobraziliense.com.br, 18.08.2018. Adaptado.)\n\nO excerto expressa uma ação de",
