  "detail": "Economia, indústria e globalização",
  "difficulty": "Média",
  "statement": "O presidente americano, Donald Trump, anunciou em 08.05.2018 algo que há meses vinha ameaçando fazer: os Estados Unidos vão sair do acordo nuclear firmado em 2015 com o Irã. Logo após o anúncio, Trump assinou uma ordem presidencial para impor novas sanções econômicas ao país do Oriente Médio.\n\n(www.nexojornal.com.br. Adaptado.)\n\nPara o Irã, uma consequência da saída dos Estados Unidos do acordo nuclear de 2015 é:",
