  "statement": "Texto 1\n\nO sarampo era considerado uma doença erradicada no Brasil desde 2016, quando a Organização Mundial da Saúde (OMS) identificou que o país estava há um ano sem registro de casos do vírus. Mas isso mudou em 2018: boletins recentes da entidade advertem que está em curso um surto da doença, altamente contagiosa e que pode levar à morte crianças pequenas ou causar sequelas graves.\n\nO Ministério da Saúde, por sua vez, informou haver alto risco de retorno da poliomielite em pelo menos 312 cidades brasileiras. A doença era considerada erradicada na América do Sul desde 1994, após décadas provocando milhares de casos de paralisia infantil. A preocupação com a pólio se dá pelo fato de que, embora não tenha havido casos recentes no Brasil, identificou-se um registro da doença na vizinha Venezuela e a circulação do vírus em outros 23 países do mundo nos últimos três anos.\n\nOs alertas acima colocam em evidência doenças que estavam controladas graças à vacinação em massa, mas que ameaçam provocar estragos na saúde pública brasileira caso a imunização sofra baixas. “Por não termos mais contato com algumas doenças infecciosas, a percepção é que elas deixaram de existir e que a vacinação é inútil. Mas poucas intervenções da medicina foram tão eficazes como as vacinas, capazes de erradicar doenças que antes matavam muitas pessoas”, avalia o pesquisador do Serviço de Bacteriologia do Instituto Butantan, Paulo Lee Ho.\n\n(Laís Modelli. “Sarampo, pólio, difteria e rubéola voltam a ameaçar após erradicação no Brasil”. www.bbc.com, 07.07.2018. Adaptado.)\n\nTexto 2\n\nEmbora o Brasil tenha um dos mais reconhecidos programas públicos de vacinação do mundo, com os principais imunizantes disponíveis a todos gratuitamente, vêm ganhando força no país grupos que se recusam a vacinar os filhos ou a si próprios.\n\nEsses movimentos “antivacina” estão sendo apontados como um dos principais fatores responsáveis por um recente surto de sarampo na Europa, onde mais de 7 mil pessoas já foram contaminadas. No Brasil, os grupos, principalmente de pais, são impulsionados por meio de páginas temáticas em redes sociais que divulgam, sem base científica, supostos efeitos colaterais das vacinas.\n\nOs pais também trocam informações sobre como não serem denunciados (por exemplo, não informar aos pediatras sobre a decisão de não vacinar os filhos) e compartilham estratégias que eles acreditam que garantiriam a imunização das crianças de forma alternativa, com óleos, homeopatia e alimentos.\n\n(Fabiana Cambricoli e Isabela Palhares. “Grupos contrários à vacinação avançam no país; movimento preocupa Ministério da Saúde”.\n\nhttps://noticias.uol.com.br, 22.05.2017. Adaptado.)\n\nTexto 3\n\nRio de Janeiro, início do século XX. Uma cidade com cerca de 700 mil habitantes e graves problemas urbanos: rede insuficiente de água e esgoto, toneladas de lixo nas ruas, cortiços superpovoados. Um ambiente propício à proliferação de várias doenças, o Rio era conhecido pelos imigrantes que aqui aportavam como “túmulo de estrangeiros”.\n\nNessa época, Oswaldo Cruz criou as Brigadas Mata-Mosquitos, formadas por grupos de funcionários do Serviço Sanitário que, acompanhados de policiais, invadiam as casas – e tinham até mesmo autoridade para mandar derrubá-las nos casos em que as considerassem uma ameaça à saúde pública – para desinfecção e extermínio dos mosquitos transmissores da febre amarela. Para acabar com os ratos, transmissores da peste bubônica, ele mandou espalhar raticida pela cidade e tornou obrigatório o recolhimento do lixo pela população. E, finalmente, para erradicar a varíola, lançou a vacinação obrigatória, medida que se tornou o estopim de uma revolta da população. Apesar das divergências estatísticas, sabe-se que a Revolta da Vacina foi o maior motim da história do Rio de Janeiro.\n\nOswaldo Cruz, vencedor da febre amarela, da peste bubônica\n\n(Rio de Janeiro. Secretaria Especial de Comunicação Social. 1904 – Revolta da Vacina. A maior batalha do Rio, 2006. Adaptado.)\n\ne da varíola (Revista da Semana, s/d, charge de Bambino)\n\nCom base em seus conhecimentos e nos textos apresentados, escreva uma dissertação, empregando a norma-padrão da língua portuguesa, sobre o tema:\n\nObrigatoriedade da vacinação: entre a prevenção a doenças e o respeito às escolhas individuais",
